import { unstable_cache, revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

// Cached product fetcher with "products" tag
const getCachedProducts = unstable_cache(
  async () => {
    const products = await getAllProducts();
    return products;
  },
  ['products-list'],
  {
    tags: ['products'],
    revalidate: false // Only revalidate on explicit tag invalidation
  }
);

export default async function AdminCatalogPage() {
  const products = await getCachedProducts();

  // Inline Server Action for sync trigger
  async function syncCatalog() {
    'use server';

    // Simulate background sync job (non-blocking for the client)
    // In production, this would trigger a queue job or webhook to your ERP/PIM
    setTimeout(async () => {
      // After sync completes, invalidate the cache
      revalidateTag('products');
    }, 0);

    // Immediately invalidate to trigger fresh data fetch on next page load
    revalidateTag('products');
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
        <h1 style={{ margin: 0, fontSize: '2rem' }}>Product Catalog</h1>

        {/* Sync form with inline Server Action */}
        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.75rem 1.5rem',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              fontSize: '1rem',
              cursor: 'pointer',
              fontWeight: 500
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <div style={{
        backgroundColor: '#f5f5f5',
        padding: '0.75rem 1rem',
        borderRadius: '6px',
        marginBottom: '1.5rem',
        fontSize: '0.875rem',
        color: '#666'
      }}>
        📊 Showing {products.length} products (cached for fast browsing)
      </div>

      <div style={{ display: 'grid', gap: '1rem' }}>
        {products.map((product) => (
          <div
            key={product.id}
            style={{
              padding: '1.5rem',
              backgroundColor: 'white',
              border: '1px solid #e0e0e0',
              borderRadius: '8px',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center'
            }}
          >
            <div>
              <h3 style={{ margin: '0 0 0.5rem 0', fontSize: '1.25rem' }}>
                {product.name}
              </h3>
              <p style={{ margin: 0, color: '#666', fontSize: '0.875rem' }}>
                Product ID: {product.id}
              </p>
            </div>
            <div style={{ fontSize: '1.5rem', fontWeight: 'bold', color: '#0070f3' }}>
              ${product.price}
            </div>
          </div>
        ))}
      </div>

      <div style={{
        marginTop: '2rem',
        padding: '1rem',
        backgroundColor: '#fffbeb',
        border: '1px solid #fde68a',
        borderRadius: '6px',
        fontSize: '0.875rem'
      }}>
        <strong>ℹ️ How sync works:</strong>
        <ul style={{ margin: '0.5rem 0 0 0', paddingLeft: '1.5rem' }}>
          <li>Click "Sync latest catalog" to trigger background refresh</li>
          <li>You can continue working immediately after submission</li>
          <li>Data updates shortly after and stays fresh across all catalog views</li>
          <li>Uses cache tag "products" for consistent invalidation</li>
        </ul>
      </div>
    </div>
  );
}

